// Re-exported for any caller that still expects the old terrain helper.
export function crystalRock(w, x, z, scale = 1) {
  const mat = standardMaterial({ color: 0x3b7fa6, emissive: 0x0d3a58, emissiveIntensity: 0.5, roughness: 0.4, metalness: 0.25 })
  const mesh = new THREE.Mesh(rockGeometry(1), mat)
  mesh.position.set(x, mazeHeight(x, z) + scale * 0.3, z)
  mesh.scale.setScalar(scale)
  mesh.castShadow = true
  return mesh
}

input.content:
:root {
  --ink: #eaf6ff;
  --muted: #a6c4d6;
  --faint: rgba(190, 222, 238, 0.5);
  --glass: rgba(7, 20, 34, 0.6);
  --glass-strong: rgba(5, 15, 26, 0.88);
  --line: rgba(150, 214, 240, 0.18);
  --lumen: #7fe6ff;
  --lumen-soft: #d6f7ff;
  --gold: #ffd98a;
  --violet: #b8a4ff;
  --danger: #ff977f;
  --heart: #ff9bb0;
  --accent: #7fe6ff;
  --serif: "Cormorant Garamond", "Iowan Old Style", "Palatino Linotype", Palatino, Georgia, serif;
  --sans: "Avenir Next", Avenir, "Segoe UI", Inter, system-ui, -apple-system, sans-serif;
}

* { box-sizing: border-box; }
html, body { margin: 0; height: 100%; overflow: hidden; background: #04121f; color: var(--ink); }
body {
  font-family: var(--sans);
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
  overscroll-behavior: none;
  -webkit-user-select: none;
  user-select: none;
}
button, input { font: inherit; }
button { cursor: pointer; }
.hidden { display: none !important; }
.sr-only { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0,0,0,0); white-space: nowrap; border: 0; }

#app { position: fixed; inset: 0; overflow: hidden; }
#world { position: absolute; inset: 0; width: 100%; height: 100%; display: block; touch-action: none; }

#grade {
  position: absolute; inset: 0; pointer-events: none; z-index: 2;
  background:
    radial-gradient(ellipse at 50% 48%, transparent 42%, rgba(2, 10, 20, 0.24) 78%, rgba(1, 6, 13, 0.66) 100%),
    linear-gradient(180deg, rgba(8, 30, 50, 0.16), transparent 22%, transparent 74%, rgba(2, 10, 18, 0.3));
  mix-blend-mode: multiply;
}

.screen {
  position: absolute; inset: 0; z-index: 20;
  display: flex; align-items: center; justify-content: center;
  padding: max(22px, env(safe-area-inset-top)) max(22px, env(safe-area-inset-right)) max(22px, env(safe-area-inset-bottom)) max(22px, env(safe-area-inset-left));
  transition: opacity 0.8s ease, visibility 0.8s;
}
.screen.fading { opacity: 0; visibility: hidden; }

/* ------------------------------------------------------------------ */
/* Cover                                                              */
/* ------------------------------------------------------------------ */
.cover { z-index: 25; overflow: hidden; background: #04121f; }
.cover-bg { position: absolute; inset: 0; pointer-events: none; overflow: hidden; }
.cover-aurora {
  position: absolute; inset: -30%;
  background:
    radial-gradient(circle at 28% 32%, rgba(80, 200, 255, 0.22), transparent 38%),
    radial-gradient(circle at 72% 62%, rgba(126, 160, 255, 0.2), transparent 42%),
    radial-gradient(circle at 50% 92%, rgba(24, 96, 150, 0.36), transparent 55%);
  filter: blur(30px);
  animation: auroraDrift 24s ease-in-out infinite alternate;
}
@keyframes auroraDrift {
  0% { transform: translate3d(-2%, -1%, 0) scale(1); opacity: 0.85; }
  50% { transform: translate3d(2%, 2%, 0) scale(1.06); opacity: 1; }
  100% { transform: translate3d(-1%, 3%, 0) scale(1.02); opacity: 0.9; }
}
.cover-rings {
  position: absolute; left: 50%; top: 52%; width: min(1180px, 150vw); aspect-ratio: 1;
  transform: translate(-50%, -50%);
  border-radius: 50%;
  background:
    repeating-radial-gradient(circle at center, transparent 0 58px, rgba(127, 230, 255, 0.09) 59px, transparent 61px),
    radial-gradient(circle at center, rgba(127, 230, 255, 0.1), transparent 62%);
  -webkit-mask-image: radial-gradient(circle at center, #000 20%, rgba(0,0,0,0.55) 62%, transparent 78%);
  mask-image: radial-gradient(circle at center, #000 20%, rgba(0,0,0,0.55) 62%, transparent 78%);
  animation: ringSpin 110s linear infinite;
}
@keyframes ringSpin { to { transform: translate(-50%, -50%) rotate(360deg); } }
.cover-floor {
  position: absolute; left: -10%; right: -10%; bottom: -8%; height: 42%;
  background:
    linear-gradient(180deg, transparent, rgba(127, 230, 255, 0.07) 55%, rgba(4, 18, 31, 0.9)),
    repeating-linear-gradient(90deg, rgba(127, 230, 255, 0.06) 0 1px, transparent 1px 92px);
  transform: perspective(420px) rotateX(58deg);
  transform-origin: bottom center;
}
.cover-shards { position: absolute; inset: 0; }
.cover-shards i {
  position: absolute; display: block;
  background: linear-gradient(155deg, rgba(214, 247, 255, 0.9), rgba(64, 158, 210, 0.35) 55%, rgba(127, 230, 255, 0.05));
  clip-path: polygon(50% 0, 100% 58%, 50% 100%, 0 42%);
  filter: drop-shadow(0 0 10px rgba(127, 230, 255, 0.35));
  animation: shardFloat var(--duration, 14s) ease-in-out infinite;
  animation-delay: var(--delay, 0s);
  will-change: transform;
}
@keyframes shardFloat {
  0%, 100% { transform: translate3d(0, 0, 0) rotate(0deg); }
  50% { transform: translate3d(var(--drift, 20px), -26px, 0) rotate(8deg); }
}
.cover-veil {
  position: absolute; inset: 0; pointer-events: none;
  background:
    radial-gradient(ellipse at 50% 45%, rgba(4, 18, 31, 0.1) 0%, rgba(4, 18, 31, 0.45) 58%, rgba(3, 12, 22, 0.86) 100%),
    linear-gradient(180deg, rgba(4, 18, 31, 0.5), transparent 26%, transparent 68%, rgba(3, 11, 20, 0.8));
}
.cover-inner {
  position: relative; z-index: 2; width: min(760px, 100%);
  text-align: center; display: flex; flex-direction: column; align-items: center;
  animation: coverRise 1.1s cubic-bezier(0.2, 0.7, 0.2, 1) both;
}
@keyframes coverRise { from { opacity: 0; transform: translateY(18px); } }
.cover-inner .brand-mark {
  width: 62px; height: 62px; margin: 0 0 20px;
  filter: drop-shadow(0 0 24px rgba(127, 230, 255, 0.6));
}
.cover-inner .eyebrow { margin-bottom: 16px; }
.cover h1 {
  margin: 0; font-family: var(--serif); font-weight: 400;
  font-size: clamp(54px, 10.5vw, 128px); line-height: 0.9; letter-spacing: 0.14em;
  color: #f4fdff;
  text-shadow: 0 0 60px rgba(127, 230, 255, 0.35), 0 0 120px rgba(64, 150, 220, 0.25);
}
.cover-sub {
  margin: 16px 0 0; font-family: var(--serif); font-size: clamp(17px, 2.2vw, 26px);
  letter-spacing: 0.42em; text-transform: uppercase; color: var(--lumen-soft);
}
.cover .tagline { margin: 16px 0 0; }
.cover-stats {
  display: grid; grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 1px; width: min(560px, 100%); margin: 34px auto 30px;
  border: 1px solid var(--line); background: var(--line);
}
.cover-stats div {
  display: flex; flex-direction: column; gap: 4px; padding: 14px 8px;
  background: rgba(5, 17, 29, 0.72); backdrop-filter: blur(10px);
}
.cover-stats span { font-family: var(--serif); font-size: clamp(19px, 2.4vw, 26px); color: var(--lumen-soft); line-height: 1; }
.cover-stats i { font-style: normal; font-size: 8px; letter-spacing: 0.16em; text-transform: uppercase; color: var(--faint); }
.cover-btn { width: min(330px, 100%); margin: 0 auto; }
.cover .micro-copy { max-width: 470px; }
.cover-footer {
  position: absolute; left: 0; right: 0; bottom: max(18px, env(safe-area-inset-bottom));
  display: flex; justify-content: center; gap: 14px; align-items: center;
  font-size: 9px; letter-spacing: 0.24em; text-transform: uppercase;
  color: rgba(166, 196, 214, 0.5); z-index: 2; padding: 0 20px; text-align: center;
}
.cover-footer .dot { color: var(--lumen); opacity: 0.7; }

/* ------------------------------------------------------------------ */
/* Planner                                                            */
/* ------------------------------------------------------------------ */
#intro { background: linear-gradient(90deg, rgba(3, 13, 24, 0.9) 0%, rgba(3, 13, 24, 0.58) 46%, rgba(3, 13, 24, 0.06) 78%); }
.intro-bg {
  position: absolute; inset: 0; pointer-events: none;
  background:
    radial-gradient(ellipse at 76% 34%, rgba(127, 230, 255, 0.13), transparent 34%),
    radial-gradient(ellipse at 18% 78%, rgba(143, 180, 255, 0.1), transparent 42%),
    linear-gradient(180deg, rgba(4, 18, 31, 0.05), rgba(4, 18, 31, 0.42));
}
.intro-inner {
  position: relative; width: min(1180px, 100%); height: min(840px, 100%);
  display: grid; grid-template-columns: minmax(0, 1fr) minmax(400px, 1.05fr);
  grid-template-rows: 1fr auto; gap: 26px 52px; align-items: center;
}
.brand { grid-column: 1; grid-row: 1; align-self: end; padding-bottom: 18px; }
.brand-mark { display: block; width: 46px; height: 46px; color: var(--lumen); margin-bottom: 22px; filter: drop-shadow(0 0 16px rgba(127, 230, 255, 0.55)); }
.brand-mark svg { width: 100%; height: 100%; }
.eyebrow, .overlay-kicker, .hud-label {
  margin: 0 0 10px; font-size: 10px; letter-spacing: 0.34em; text-transform: uppercase; color: var(--lumen);
}
.brand h1 {
  margin: 0; font-family: var(--serif); font-weight: 400; font-size: clamp(40px, 4.6vw, 68px);
  letter-spacing: 0.08em; line-height: 0.94; color: #f2fdff;
  text-shadow: 0 0 40px rgba(127, 230, 255, 0.24);
}
.tagline { margin: 18px 0 0; font-family: var(--serif); font-size: clamp(15px, 1.45vw, 21px); font-style: italic; color: var(--muted); letter-spacing: 0.03em; }

.rite-card {
  grid-column: 2; grid-row: 1 / span 2; align-self: center;
  width: 100%; max-width: 680px; justify-self: end;
  padding: 32px 34px 26px; border: 1px solid var(--line); border-radius: 4px;
  background: linear-gradient(155deg, rgba(7, 24, 40, 0.9), rgba(5, 16, 28, 0.76));
  backdrop-filter: blur(22px) saturate(1.2); -webkit-backdrop-filter: blur(22px) saturate(1.2);
  box-shadow: 0 40px 100px rgba(0, 0, 0, 0.5), inset 0 1px 0 rgba(255, 255, 255, 0.05);
  max-height: calc(100% - 8px); overflow: auto; scrollbar-width: thin; scrollbar-color: rgba(127,230,255,0.3) transparent;
}
.rite-step { padding: 4px 0 20px; }
.rite-step + .rite-step { border-top: 1px solid var(--line); padding-top: 20px; }
.rite-step.compact { padding: 16px 0; }
.step-head { display: flex; gap: 16px; align-items: flex-start; margin-bottom: 16px; }
.step-index {
  flex: 0 0 auto; width: 28px; height: 28px; display: grid; place-items: center;
  border: 1px solid rgba(127, 230, 255, 0.35); border-radius: 50%;
  font-family: var(--serif); font-size: 13px; color: var(--lumen);
}
.step-head h2 { margin: 0 0 3px; font-family: var(--serif); font-size: 24px; font-weight: 500; letter-spacing: 0.02em; }
.step-head p { margin: 0; color: var(--muted); font-size: 12.5px; line-height: 1.5; }

.friend-strip { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 8px; }
.friend-chip {
  display: flex; align-items: center; gap: 10px; min-width: 0;
  padding: 10px 11px; border: 1px solid var(--line); border-radius: 3px;
  background: rgba(255, 255, 255, 0.02);
}
.friend-chip.locked { opacity: 0.46; }
.friend-chip .friend-glyph { color: var(--friend-color, var(--lumen)); font-size: 20px; line-height: 1; flex: 0 0 auto; text-shadow: 0 0 12px var(--friend-color, var(--lumen)); }
.friend-chip div { min-width: 0; }
.friend-chip strong { display: block; font-size: 12px; font-weight: 600; letter-spacing: 0.03em; }
.friend-chip div span { display: block; margin-top: 2px; font-size: 9px; line-height: 1.3; color: var(--faint); }

.focus-field { position: relative; display: block; }
.focus-field input {
  width: 100%; height: 54px; padding: 0 44px 0 16px; border: 1px solid var(--line); border-radius: 3px;
  background: rgba(255, 255, 255, 0.028); color: var(--ink); font-family: var(--serif); font-size: 18px;
  outline: none; transition: border-color 0.2s, box-shadow 0.2s;
}
.focus-field input::placeholder { color: rgba(196, 224, 236, 0.34); font-style: italic; }
.focus-field input:focus { border-color: rgba(127, 230, 255, 0.58); box-shadow: 0 0 0 3px rgba(127, 230, 255, 0.08); }
.focus-glyph { position: absolute; right: 16px; top: 50%; transform: translateY(-50%); color: var(--lumen); opacity: 0.6; }

.technique-grid { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 6px; margin-top: 12px; }
.technique-chip {
  display: flex; flex-direction: column; align-items: flex-start; gap: 2px;
  padding: 8px 9px; border: 1px solid var(--line); border-radius: 3px;
  background: rgba(255, 255, 255, 0.018); color: var(--ink); text-align: left;
  transition: border-color 0.2s, background 0.2s, transform 0.2s;
}
.technique-chip:hover { border-color: var(--tech-accent, var(--lumen)); background: rgba(127, 230, 255, 0.06); transform: translateY(-1px); }
.technique-chip.active {
  border-color: var(--tech-accent, var(--lumen));
  background: color-mix(in srgb, var(--tech-accent, var(--lumen)) 14%, transparent);
  box-shadow: inset 0 0 20px rgba(127, 230, 255, 0.06);
}
.technique-chip .t-glyph { font-size: 15px; line-height: 1.1; color: var(--tech-accent, var(--lumen)); }
.technique-chip .t-name { font-size: 9px; letter-spacing: 0.05em; text-transform: uppercase; color: #dceef8; }
.technique-chip .t-min { font-size: 8px; letter-spacing: 0.06em; color: var(--faint); }

.task-meta { display: flex; align-items: center; justify-content: space-between; gap: 12px; margin-top: 12px; }
.minutes-field {
  display: flex; align-items: center; gap: 9px;
  font-size: 9.5px; letter-spacing: 0.16em; text-transform: uppercase; color: var(--muted);
}
.minutes-field input {
  width: 66px; height: 40px; padding: 0 8px; text-align: center;
  border: 1px solid var(--line); border-radius: 3px; background: rgba(255, 255, 255, 0.028);
  color: var(--ink); font-family: var(--serif); font-size: 16px; outline: none;
}
.minutes-field input:focus { border-color: rgba(127, 230, 255, 0.5); }
.add-task-btn { flex: 0 0 auto; width: auto; height: 40px; padding: 0 20px; font-size: 9.5px; }

.focus-hint { margin: 10px 0 0; color: var(--faint); font-size: 11.5px; line-height: 1.45; }
.focus-hint b { color: var(--ink); font-weight: 600; }
.focus-hint.matched { color: var(--lumen); }

.suggestion-row { display: flex; flex-wrap: wrap; gap: 6px; margin: 14px 0 4px; }
.suggestion-chip {
  display: inline-flex; align-items: center; gap: 6px;
  padding: 6px 10px; border: 1px dashed var(--line); border-radius: 20px;
  background: transparent; color: var(--muted); font-size: 10px; line-height: 1.2;
  transition: color 0.2s, border-color 0.2s, background 0.2s;
}
.suggestion-chip span { color: var(--lumen); font-size: 11px; }
.suggestion-chip:hover { color: var(--ink); border-color: rgba(127, 230, 255, 0.45); background: rgba(127, 230, 255, 0.05); }

.task-list { display: grid; gap: 6px; margin-top: 12px; }
.task-row {
  display: flex; align-items: center; gap: 10px;
  padding: 9px 11px; border: 1px solid var(--line); border-left: 2px solid var(--tech-accent, var(--lumen));
  border-radius: 2px; background: rgba(255, 255, 255, 0.025);
  animation: taskIn 0.3s ease both;
}
@keyframes taskIn { from { opacity: 0; transform: translateY(-3px); } }
.task-index { flex: 0 0 auto; font-family: var(--serif); font-size: 11px; color: var(--faint); }
.task-glyph { flex: 0 0 auto; width: 18px; text-align: center; font-size: 14px; color: var(--tech-accent, var(--lumen)); }
.task-copy { flex: 1 1 auto; min-width: 0; }
.task-copy strong { display: block; font-size: 12.5px; font-weight: 500; line-height: 1.3; overflow-wrap: anywhere; }
.task-copy span { display: block; margin-top: 2px; font-size: 9px; letter-spacing: 0.06em; color: var(--faint); text-transform: uppercase; }
.task-remove {
  flex: 0 0 auto; width: 26px; height: 26px; display: grid; place-items: center;
  border: 1px solid transparent; border-radius: 50%; background: transparent;
  color: var(--faint); font-size: 11px; transition: color 0.2s, border-color 0.2s;
}
.task-remove:hover { color: var(--danger); border-color: rgba(255, 151, 127, 0.4); }
.task-empty { margin: 14px 0 0; padding: 10px 0; text-align: center; font-size: 11.5px; font-style: italic; color: var(--faint); }

.rite-oath { display: flex; gap: 13px; align-items: flex-start; }
.oath-rune { color: var(--gold); font-size: 20px; line-height: 1.3; }
.rite-oath p { margin: 0; font-size: 12px; line-height: 1.55; color: var(--muted); }
.rite-oath strong { color: var(--ink); font-weight: 600; }

.planner-actions { display: flex; align-items: center; justify-content: space-between; gap: 12px; margin: 4px 0 14px; padding-top: 14px; border-top: 1px solid var(--line); }
.market-btn { flex: 0 0 auto; width: auto; height: 42px; padding: 0 16px; display: flex; align-items: center; gap: 10px; }
.market-btn b { color: var(--lumen); font-size: 10px; letter-spacing: 0.08em; }
.planner-pace { font-size: 9px; letter-spacing: 0.16em; text-transform: uppercase; color: var(--faint); }

.primary-btn {
  width: 100%; display: flex; align-items: center; justify-content: center; gap: 12px;
  height: 54px; border: 1px solid rgba(127, 230, 255, 0.5); border-radius: 3px;
  background: linear-gradient(110deg, rgba(127, 230, 255, 0.17), rgba(127, 230, 255, 0.05));
  color: var(--lumen-soft); font-size: 12px; letter-spacing: 0.24em; text-transform: uppercase;
  transition: background 0.25s, border-color 0.25s, box-shadow 0.25s, opacity 0.25s;
}
.primary-btn svg { width: 19px; height: 19px; }
.primary-btn:hover:not(:disabled) { background: linear-gradient(110deg, rgba(127, 230, 255, 0.3), rgba(127, 230, 255, 0.1)); border-color: var(--lumen); box-shadow: 0 0 34px rgba(127, 230, 255, 0.18); }
.primary-btn:disabled { opacity: 0.35; cursor: not-allowed; }
.primary-btn.small { width: auto; height: 44px; padding: 0 22px; font-size: 10px; }
.micro-copy { margin: 12px 0 0; text-align: center; font-size: 10px; letter-spacing: 0.06em; color: rgba(166, 196, 214, 0.55); }

.intro-footer {
  grid-column: 1; grid-row: 2; align-self: end; display: flex; gap: 14px; align-items: center;
  font-size: 9.5px; letter-spacing: 0.24em; text-transform: uppercase; color: rgba(166, 196, 214, 0.54);
}
.intro-footer .dot { color: var(--lumen); opacity: 0.6; }

/* ------------------------------------------------------------------ */
/* HUD                                                                */
/* ------------------------------------------------------------------ */
#hud { position: absolute; inset: 0; z-index: 10; pointer-events: none; }
.hud-top { position: absolute; top: max(16px, env(safe-area-inset-top)); left: max(16px, env(safe-area-inset-left)); right: max(16px, env(safe-area-inset-right)); display: flex; align-items: flex-start; justify-content: space-between; gap: 14px; }
.study-card, .objective-card, .vitals-card {
  padding: 12px 15px 11px; border: 1px solid var(--line); border-radius: 3px;
  background: linear-gradient(145deg, rgba(6, 22, 38, 0.76), rgba(5, 16, 28, 0.5));
  backdrop-filter: blur(14px); -webkit-backdrop-filter: blur(14px);
  box-shadow: 0 12px 40px rgba(0, 0, 0, 0.24);
}
.study-card { min-width: 250px; max-width: 340px; }
.study-line { display: flex; align-items: baseline; gap: 10px; flex-wrap: wrap; }
.subject-pill { color: var(--accent); font-size: 12px; letter-spacing: 0.12em; text-transform: uppercase; }
.study-focus { font-family: var(--serif); font-size: 17px; color: var(--ink); line-height: 1.2; }
.hud-sector { display: block; margin-top: 6px; font-size: 9px; letter-spacing: 0.2em; text-transform: uppercase; color: var(--faint); }

.day-clock { display: flex; align-items: center; gap: 8px; margin-top: 9px; font-size: 9px; letter-spacing: 0.08em; color: var(--faint); }
.day-clock > span:first-child { font-family: var(--serif); font-size: 13px; color: var(--lumen-soft); letter-spacing: 0.04em; }
.day-track { position: relative; flex: 1 1 auto; height: 3px; border-radius: 2px; background: rgba(127, 230, 255, 0.14); overflow: hidden; }
.day-track i { display: block; width: 0%; height: 100%; background: linear-gradient(90deg, rgba(127, 230, 255, 0.5), var(--lumen)); box-shadow: 0 0 8px rgba(127, 230, 255, 0.6); transition: width 0.4s linear, background 0.4s; }
.day-track i.late { background: linear-gradient(90deg, var(--lumen), var(--gold)); }
.day-track i.critical { background: linear-gradient(90deg, var(--gold), var(--danger)); }

.objective-card { text-align: center; min-width: 250px; max-width: 360px; }
.mission-dots { display: flex; gap: 7px; justify-content: center; margin: 5px 0 6px; }
.mission-dots i { width: 7px; height: 7px; transform: rotate(45deg); border: 1px solid rgba(127, 230, 255, 0.4); background: transparent; transition: background 0.3s, box-shadow 0.3s, border-color 0.3s; }
.mission-dots i.done { background: var(--lumen); border-color: var(--lumen); box-shadow: 0 0 10px rgba(127, 230, 255, 0.8); }
.mission-dots i.failed { border-color: var(--danger); background: rgba(255, 151, 127, 0.3); box-shadow: 0 0 8px rgba(255, 151, 127, 0.4); }
.mission-dots i.current { border-color: var(--gold); box-shadow: 0 0 7px rgba(255, 217, 138, 0.6); }
.objective-text { display: block; font-family: var(--serif); font-size: 15px; color: #e6f7ff; line-height: 1.3; }
.objective-timer { display: block; margin-top: 3px; font-size: 8.5px; letter-spacing: 0.14em; text-transform: uppercase; color: var(--faint); }

.hud-actions { display: flex; gap: 9px; align-items: stretch; }
.vitals-card { min-width: 118px; text-align: right; }
.heart-pips { display: flex; gap: 5px; justify-content: flex-end; margin: 6px 0 5px; }
.heart-pips i { width: 9px; height: 9px; transform: rotate(45deg); border: 1px solid rgba(255, 155, 176, 0.42); background: transparent; transition: background 0.3s, box-shadow 0.3s; }
.heart-pips i.full { background: var(--heart); border-color: var(--heart); box-shadow: 0 0 9px rgba(255, 155, 176, 0.6); }
.heart-pips i.spent { opacity: 0.32; }
.weakness-pips { display: flex; gap: 4px; justify-content: flex-end; margin-bottom: 4px; }
.weakness-pips i { width: 10px; height: 4px; border-radius: 1px; border: 1px solid rgba(255, 151, 127, 0.28); background: rgba(255, 151, 127, 0.04); transition: background 0.3s, box-shadow 0.3s; }
.weakness-pips i.full { background: var(--danger); border-color: var(--danger); box-shadow: 0 0 8px rgba(255, 151, 127, 0.5); }
.charge-text { font-size: 9px; letter-spacing: 0.12em; text-transform: uppercase; color: var(--faint); }
.charge-text.ready { color: var(--lumen); }
.charge-text.danger { color: var(--danger); }

.icon-btn {
  width: 44px; min-width: 44px; height: 44px; display: grid; place-items: center; padding: 0;
  border: 1px solid var(--line); border-radius: 3px; background: rgba(6, 22, 38, 0.66); color: var(--muted);
  backdrop-filter: blur(12px); -webkit-backdrop-filter: blur(12px); pointer-events: auto; transition: color 0.2s, border-color 0.2s;
}
.icon-btn:hover { color: var(--lumen); border-color: rgba(127, 230, 255, 0.42); }
.icon-btn svg { width: 20px; height: 20px; }

.crosshair { position: absolute; left: 50%; top: 50%; width: 42px; height: 42px; transform: translate(-50%, -50%); opacity: 0.7; transition: opacity 0.2s; }
.ch-ring { position: absolute; inset: 10px; border: 1px solid rgba(214, 247, 255, 0.28); border-radius: 50%; }
.ch-diamond { position: absolute; left: 50%; top: 50%; width: 5px; height: 5px; transform: translate(-50%, -50%) rotate(45deg); background: var(--lumen-soft); box-shadow: 0 0 8px var(--lumen); }
.ch-tick { position: absolute; background: rgba(214, 247, 255, 0.42); }
.ch-tick.top, .ch-tick.bottom { width: 1px; height: 5px; left: 50%; }
.ch-tick.top { top: 1px; } .ch-tick.bottom { bottom: 1px; }
.ch-tick.left, .ch-tick.right { height: 1px; width: 5px; top: 50%; }
.ch-tick.left { left: 1px; } .ch-tick.right { right: 1px; }
.crosshair.targeting { opacity: 1; }
.crosshair.targeting .ch-ring { border-color: var(--gold); box-shadow: 0 0 16px rgba(255, 217, 138, 0.4); }

.target-tag {
  position: absolute; left: 50%; top: calc(50% + 42px); transform: translateX(-50%);
  display: flex; flex-direction: column; align-items: center; gap: 1px; padding: 7px 14px;
  border: 1px solid rgba(255, 217, 138, 0.28); background: rgba(6, 20, 34, 0.72); backdrop-filter: blur(8px);
  border-radius: 2px; text-align: center;
}
.target-tag span { color: var(--gold); font-size: 13px; }
.target-tag b { font-size: 10px; letter-spacing: 0.18em; text-transform: uppercase; color: var(--gold); }
.target-tag i { font-style: normal; font-size: 9px; letter-spacing: 0.05em; color: var(--faint); }

.prompt { position: absolute; left: 50%; bottom: 19%; transform: translateX(-50%); pointer-events: auto; }
.prompt-btn {
  display: flex; align-items: center; gap: 12px; padding: 12px 20px 12px 12px;
  border: 1px solid rgba(127, 230, 255, 0.48); border-radius: 3px;
  background: rgba(5, 22, 38, 0.9); color: var(--lumen-soft);
  font-size: 11px; letter-spacing: 0.18em; text-transform: uppercase;
  box-shadow: 0 0 40px rgba(127, 230, 255, 0.16), inset 0 1px 0 rgba(255, 255, 255, 0.06);
  backdrop-filter: blur(12px); animation: promptPulse 2.6s ease-in-out infinite;
}
.prompt-btn .key { display: grid; place-items: center; width: 27px; height: 27px; border: 1px solid rgba(127, 230, 255, 0.5); border-radius: 2px; font-size: 11px; }
.prompt-btn:active { transform: scale(0.98); }
@keyframes promptPulse { 0%, 100% { box-shadow: 0 0 30px rgba(127, 230, 255, 0.12); } 50% { box-shadow: 0 0 52px rgba(127, 230, 255, 0.26); } }

.toast {
  position: absolute; left: 50%; top: 15%; transform: translateX(-50%); z-index: 75;
  padding: 10px 18px; border: 1px solid var(--line); border-radius: 2px;
  background: rgba(5, 18, 31, 0.9); backdrop-filter: blur(12px);
  font-size: 11px; letter-spacing: 0.08em; color: var(--ink); text-align: center;
  max-width: min(520px, 84vw); pointer-events: none;
  animation: toastIn 0.32s ease;
}
@keyframes toastIn { from { opacity: 0; transform: translate(-50%, -6px); } }

.touch-layer { position: absolute; inset: 0; pointer-events: none; }
.joystick {
  position: absolute; left: max(25px, env(safe-area-inset-left)); bottom: max(28px, env(safe-area-inset-bottom));
  width: 128px; height: 128px; pointer-events: auto; touch-action: none;
  border-radius: 50%; background: radial-gradient(circle, rgba(127, 230, 255, 0.05), rgba(3, 14, 24, 0.22) 65%, transparent 68%);
}
.joy-ring { position: absolute; inset: 11px; border: 1px solid rgba(180, 228, 245, 0.25); border-radius: 50%; }
.joy-ring::before, .joy-ring::after { content: ""; position: absolute; background: rgba(180, 228, 245, 0.1); }
.joy-ring::before { left: 50%; top: 12px; bottom: 12px; width: 1px; }
.joy-ring::after { top: 50%; left: 12px; right: 12px; height: 1px; }
.joy-thumb {
  position: absolute; left: 50%; top: 50%; width: 46px; height: 46px; margin: -23px 0 0 -23px;
  border: 1px solid rgba(127, 230, 255, 0.55); border-radius: 50%;
  background: radial-gradient(circle, rgba(127, 230, 255, 0.3), rgba(127, 230, 255, 0.06) 68%);
  box-shadow: 0 0 22px rgba(127, 230, 255, 0.18);
}
.joy-label { position: absolute; left: 50%; bottom: -18px; transform: translateX(-50%); font-size: 8px; letter-spacing: 0.22em; color: var(--faint); }
.touch-actions { position: absolute; right: max(28px, env(safe-area-inset-right)); bottom: max(30px, env(safe-area-inset-bottom)); display: flex; align-items: flex-end; gap: 16px; pointer-events: auto; }
.round-btn {
  position: relative; width: 88px; height: 88px; border-radius: 50%; border: 1px solid rgba(127, 230, 255, 0.45);
  background: radial-gradient(circle at 42% 36%, rgba(127, 230, 255, 0.22), rgba(5, 24, 40, 0.66) 68%);
  color: var(--lumen-soft); box-shadow: 0 0 34px rgba(127, 230, 255, 0.12), inset 0 0 22px rgba(127, 230, 255, 0.05);
  touch-action: none; transition: transform 0.12s, box-shadow 0.2s, opacity 0.2s;
}
.round-btn:active { transform: scale(0.94); box-shadow: 0 0 48px rgba(127, 230, 255, 0.3); }
.round-btn:disabled { opacity: 0.3; }
.fire-btn .fire-core { position: absolute; left: 50%; top: 50%; width: 24px; height: 24px; transform: translate(-50%, -55%) rotate(45deg); border: 1px solid var(--lumen); background: rgba(127, 230, 255, 0.16); box-shadow: 0 0 18px rgba(127, 230, 255, 0.35); }
.fire-btn .fire-label { position: absolute; left: 50%; bottom: 18px; transform: translateX(-50%); font-size: 8px; letter-spacing: 0.26em; color: var(--lumen); }

.hint-strip {
  position: absolute; left: 50%; bottom: max(14px, env(safe-area-inset-bottom)); transform: translateX(-50%);
  max-width: min(560px, 62vw); text-align: center; padding: 5px 14px;
  font-size: 9.5px; letter-spacing: 0.12em; color: rgba(180, 214, 230, 0.5); text-transform: uppercase;
}

/* ------------------------------------------------------------------ */
/* Overlays                                                           */
/* ------------------------------------------------------------------ */
.overlay { position: absolute; inset: 0; z-index: 40; display: flex; align-items: center; justify-content: center; padding: 20px; }
.overlay-veil { position: absolute; inset: 0; background: radial-gradient(ellipse at center, rgba(3, 12, 22, 0.4), rgba(2, 8, 15, 0.84)); backdrop-filter: blur(7px); -webkit-backdrop-filter: blur(7px); }

.ritual-panel {
  position: relative; width: min(640px, 100%); max-height: min(860px, 96vh); overflow: auto;
  padding: 30px 34px 24px; border: 1px solid rgba(127, 230, 255, 0.26); border-radius: 4px;
  background: linear-gradient(155deg, rgba(7, 24, 41, 0.95), rgba(4, 13, 24, 0.94));
  box-shadow: 0 50px 130px rgba(0, 0, 0, 0.62), inset 0 1px 0 rgba(255, 255, 255, 0.06);
}
.ritual-head { display: flex; align-items: flex-start; gap: 16px; text-align: left; }
.puzzle-sigil {
  flex: 0 0 auto; width: 54px; height: 54px; display: grid; place-items: center;
  border: 1px solid rgba(127, 230, 255, 0.34); border-radius: 50%; color: var(--accent);
  font-family: var(--serif); font-size: 26px; box-shadow: inset 0 0 22px rgba(127, 230, 255, 0.08);
}
.ritual-head h2 { margin: 2px 0 3px; font-family: var(--serif); font-weight: 500; font-size: clamp(23px, 3vw, 32px); line-height: 1.15; overflow-wrap: anywhere; }
.puzzle-focus { margin: 0; color: var(--muted); font-size: 11.5px; letter-spacing: 0.06em; }
.ritual-badge {
  margin-left: auto; flex: 0 0 auto; padding: 5px 9px;
  border: 1px solid rgba(255, 217, 138, 0.4); border-radius: 2px;
  font-size: 8px; letter-spacing: 0.2em; color: var(--gold); text-transform: uppercase;
}

.ritual-stage {
  position: relative; width: 232px; height: 232px; margin: 20px auto 6px;
  display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 2px;
}
.ritual-ring { position: absolute; inset: 0; width: 100%; height: 100%; transform: rotate(-90deg); overflow: visible; }
.ritual-track { fill: none; stroke: rgba(127, 230, 255, 0.13); stroke-width: 3; }
.ritual-arc {
  fill: none; stroke: var(--lumen); stroke-width: 3; stroke-linecap: round;
  stroke-dasharray: 552.92; stroke-dashoffset: 552.92;
  filter: drop-shadow(0 0 6px rgba(127, 230, 255, 0.75));
  transition: stroke-dashoffset 0.12s linear;
}
.ritual-core {
  position: relative; z-index: 1; font-size: 36px; line-height: 1;
  color: var(--lumen); opacity: 0.6; transition: opacity 0.3s, text-shadow 0.3s, transform 0.3s;
}
.ritual-core.lit { opacity: 1; text-shadow: 0 0 30px rgba(127, 230, 255, 0.9); animation: corePulse 1.4s ease-in-out infinite; }
@keyframes corePulse { 0%, 100% { transform: scale(1); } 50% { transform: scale(1.12); } }
.ritual-time { position: relative; z-index: 1; display: flex; flex-direction: column; align-items: center; gap: 1px; }
.ritual-time span { font-family: var(--serif); font-size: 42px; line-height: 1; color: #f0fcff; letter-spacing: 0.03em; }
.ritual-time i { font-style: normal; font-size: 8px; letter-spacing: 0.24em; text-transform: uppercase; color: var(--faint); }

.ritual-progress { height: 4px; margin: 10px 0 12px; border-radius: 2px; background: rgba(127, 230, 255, 0.12); overflow: hidden; }
.ritual-progress span { display: block; width: 0%; height: 100%; border-radius: 2px; background: linear-gradient(90deg, rgba(127, 230, 255, 0.4), var(--lumen)); box-shadow: 0 0 10px rgba(127, 230, 255, 0.7); transition: width 0.1s linear; }
.ritual-tip { margin: 0 0 18px; text-align: center; font-size: 11.5px; line-height: 1.5; color: var(--muted); }
.ritual-foot { display: flex; gap: 10px; }
.ritual-abandon { flex: 0 0 auto; width: auto; padding: 0 18px; }
.hold-btn { flex: 1 1 auto; width: auto; position: relative; overflow: hidden; }
.hold-btn.holding { border-color: var(--lumen); background: linear-gradient(110deg, rgba(127, 230, 255, 0.32), rgba(127, 230, 255, 0.12)); box-shadow: 0 0 34px rgba(127, 230, 255, 0.26); }
.hold-btn.holding span { color: #ffffff; }

/* Reward */
#reward { background: radial-gradient(ellipse at center, rgba(18, 70, 96, 0.26), rgba(2, 8, 15, 0.8)); }
.reward-glow { position: absolute; width: min(900px, 130vw); aspect-ratio: 1; border-radius: 50%; background: radial-gradient(circle, rgba(127, 230, 255, 0.2), rgba(127, 230, 255, 0.03) 44%, transparent 68%); animation: breathe 5s ease-in-out infinite; }
@keyframes breathe { 0%, 100% { transform: scale(0.94); opacity: 0.7; } 50% { transform: scale(1.05); opacity: 1; } }
.reward-panel { position: relative; width: min(660px, 100%); text-align: center; padding: 34px 34px 30px; }
.reward-rune { display: inline-block; font-size: 46px; color: var(--lumen); text-shadow: 0 0 32px rgba(127, 230, 255, 0.7); animation: spinRune 18s linear infinite; }
@keyframes spinRune { to { transform: rotate(360deg); } }
.reward-panel h2 { margin: 8px 0 12px; font-family: var(--serif); font-weight: 400; font-size: clamp(30px, 4.2vw, 50px); line-height: 1.05; }
.reward-copy { max-width: 490px; margin: 0 auto 26px; color: var(--muted); font-size: 13px; line-height: 1.6; }
.reward-stats { display: grid; grid-template-columns: repeat(3, 1fr); gap: 1px; margin: 0 auto 28px; max-width: 520px; border: 1px solid var(--line); background: var(--line); }
.reward-stats div { padding: 15px 8px; background: rgba(5, 18, 31, 0.92); display: flex; flex-direction: column; gap: 4px; }
.reward-stats span { font-family: var(--serif); font-size: 25px; color: var(--lumen-soft); }
.reward-stats i { font-style: normal; font-size: 8.5px; letter-spacing: 0.15em; text-transform: uppercase; color: var(--faint); }
.reward-panel .primary-btn { max-width: 330px; margin: 0 auto; }

/* Defeat */
#defeat { background: radial-gradient(ellipse at center, rgba(80, 30, 40, 0.2), rgba(2, 8, 15, 0.86)); }
.defeat-veil { position: absolute; inset: 0; background: radial-gradient(ellipse at 50% 40%, transparent, rgba(2, 8, 15, 0.7)); }
.defeat-panel { position: relative; width: min(620px, 100%); text-align: center; padding: 34px 32px 30px; border: 1px solid rgba(255, 151, 127, 0.22); border-radius: 4px; background: linear-gradient(155deg, rgba(30, 16, 26, 0.9), rgba(8, 12, 22, 0.94)); box-shadow: 0 50px 130px rgba(0, 0, 0, 0.66); }
.defeat-rune { display: inline-grid; place-items: center; width: 54px; height: 54px; border: 1px solid rgba(255, 151, 127, 0.45); border-radius: 50%; color: var(--danger); font-size: 20px; margin-bottom: 12px; }
.defeat-panel h2 { margin: 8px 0 12px; font-family: var(--serif); font-weight: 400; font-size: clamp(30px, 4.2vw, 48px); line-height: 1.05; }
.defeat-panel .overlay-kicker { color: var(--danger); }
.defeat-panel .reward-stats div { background: rgba(12, 14, 26, 0.92); }
.defeat-panel .reward-stats span { color: #ffd6cc; }
.defeat-panel .primary-btn { max-width: 330px; margin: 0 auto; }

/* Settings / market / friends / travel */
.settings-panel, .travel-panel {
  position: relative; width: min(560px, 100%); max-height: 92vh; overflow: auto;
  padding: 28px 30px; border: 1px solid var(--line); border-radius: 4px;
  background: linear-gradient(155deg, rgba(7, 24, 41, 0.96), rgba(4, 13, 24, 0.95));
  box-shadow: 0 50px 120px rgba(0, 0, 0, 0.62);
}
.settings-head { display: flex; align-items: flex-start; justify-content: space-between; gap: 16px; margin-bottom: 18px; }
.settings-head h2 { margin: 2px 0 0; font-family: var(--serif); font-weight: 500; font-size: 30px; }
.setting-row { display: flex; align-items: center; justify-content: space-between; gap: 20px; padding: 16px 0; border-top: 1px solid var(--line); }
.setting-row strong { display: block; font-size: 12.5px; font-weight: 600; letter-spacing: 0.03em; }
.setting-row span { display: block; margin-top: 3px; font-size: 10.5px; color: var(--faint); line-height: 1.4; }
input[type="range"] { width: 130px; accent-color: var(--lumen); background: transparent; }
.toggle { position: relative; width: 48px; height: 26px; flex: 0 0 auto; border: 1px solid var(--line); border-radius: 20px; background: rgba(255, 255, 255, 0.04); transition: background 0.2s, border-color 0.2s; }
.toggle span { position: absolute; left: 4px; top: 4px; width: 16px; height: 16px; border-radius: 50%; background: var(--muted); transition: transform 0.2s, background 0.2s; }
.toggle[aria-checked="true"] { background: rgba(127, 230, 255, 0.18); border-color: rgba(127, 230, 255, 0.55); }
.toggle[aria-checked="true"] span { transform: translateX(21px); background: var(--lumen); box-shadow: 0 0 8px var(--lumen); }

.pace-row { flex-wrap: wrap; }
.pace-group { display: flex; flex: 0 0 auto; border: 1px solid var(--line); border-radius: 3px; overflow: hidden; }
.pace-btn {
  padding: 8px 12px; border: 0; background: transparent; color: var(--muted);
  font-size: 9px; letter-spacing: 0.1em; text-transform: uppercase;
  transition: background 0.2s, color 0.2s;
}
.pace-btn + .pace-btn { border-left: 1px solid var(--line); }
.pace-btn:hover { color: var(--ink); }
.pace-btn.active { background: rgba(127, 230, 255, 0.15); color: var(--lumen-soft); }

.settings-help { margin-top: 8px; padding: 14px 16px; border: 1px solid var(--line); background: rgba(255, 255, 255, 0.018); }
.settings-help p { margin: 0 0 7px; font-size: 10.5px; line-height: 1.5; color: var(--muted); }
.settings-help p:last-child { margin-bottom: 0; }
.settings-help b { color: var(--lumen-soft); font-weight: 600; }
.settings-actions { display: flex; flex-wrap: wrap; gap: 10px; margin-top: 18px; }
.ghost-btn {
  flex: 1 1 auto; min-width: 0; height: 42px; padding: 0 12px;
  border: 1px solid var(--line); border-radius: 3px; background: transparent;
  color: var(--muted); font-size: 10px; letter-spacing: 0.13em; text-transform: uppercase;
  transition: color 0.2s, border-color 0.2s, background 0.2s;
}
.ghost-btn:hover { color: var(--ink); border-color: rgba(127, 230, 255, 0.35); background: rgba(127, 230, 255, 0.04); }
.ghost-btn.danger { color: rgba(255, 151, 127, 0.75); }
.ghost-btn.danger:hover { color: var(--danger); border-color: rgba(255, 151, 127, 0.4); }

/* Market */
.shop-panel { width: min(780px, 100%); }
.shop-top { display: flex; align-items: center; justify-content: space-between; gap: 16px; margin-bottom: 16px; }
.shop-top p { margin: 0; max-width: 480px; font-size: 11.5px; line-height: 1.5; color: var(--muted); }
.shop-shards { flex: 0 0 auto; font-family: var(--serif); font-size: 16px; color: var(--lumen-soft); white-space: nowrap; }
.shop-list, .inventory-list { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 9px; }
.shop-card, .inventory-card {
  display: flex; align-items: center; gap: 12px; min-width: 0;
  padding: 12px 13px; border: 1px solid var(--line); border-radius: 3px;
  background: rgba(255, 255, 255, 0.022);
  transition: border-color 0.2s, background 0.2s;
}
.shop-card:hover { border-color: rgba(127, 230, 255, 0.3); background: rgba(127, 230, 255, 0.035); }
.shop-card.sold { opacity: 0.48; }
.shop-glyph { flex: 0 0 auto; width: 30px; text-align: center; font-size: 24px; line-height: 1; color: var(--lumen); text-shadow: 0 0 14px rgba(127, 230, 255, 0.5); }
.shop-copy { flex: 1 1 auto; min-width: 0; }
.shop-copy strong { display: block; font-size: 12.5px; font-weight: 600; line-height: 1.3; }
.shop-copy span { display: block; margin-top: 3px; font-size: 10px; line-height: 1.4; color: var(--faint); }
.shop-buy {
  flex: 0 0 auto; min-height: 34px; padding: 0 10px;
  border: 1px solid rgba(127, 230, 255, 0.38); border-radius: 2px;
  background: rgba(127, 230, 255, 0.08); color: var(--lumen-soft);
  font-size: 8.5px; letter-spacing: 0.08em; text-transform: uppercase; line-height: 1.2;
  transition: background 0.2s, border-color 0.2s, opacity 0.2s;
}
.shop-buy:hover:not(:disabled) { background: rgba(127, 230, 255, 0.18); border-color: var(--lumen); }
.shop-buy:disabled { opacity: 0.42; cursor: default; }
.shop-buy.use { border-color: rgba(255, 217, 138, 0.4); background: rgba(255, 217, 138, 0.07); color: var(--gold); }
.shop-buy.use:hover:not(:disabled) { background: rgba(255, 217, 138, 0.16); border-color: var(--gold); }
.inventory-head { display: flex; align-items: baseline; justify-content: space-between; gap: 12px; margin: 20px 0 10px; padding-top: 16px; border-top: 1px solid var(--line); }
.inventory-head h3 { margin: 0; font-family: var(--serif); font-weight: 500; font-size: 21px; }
.inventory-head span { font-size: 9px; letter-spacing: 0.14em; text-transform: uppercase; color: var(--faint); }
.inventory-card { background: rgba(127, 230, 255, 0.028); }
.shop-help { margin-top: 18px; padding: 14px 16px; border: 1px solid var(--line); background: rgba(255, 255, 255, 0.018); }
.shop-help p { margin: 0 0 7px; font-size: 10.5px; line-height: 1.5; color: var(--muted); }
.shop-help p:last-child { margin-bottom: 0; }
.shop-help b { color: var(--lumen-soft); font-weight: 600; }

/* Friends */
.friends-panel { width: min(620px, 100%); }
.travel-copy { margin: -4px 0 18px; color: var(--muted); font-size: 11.5px; line-height: 1.5; }
.friends-list { display: grid; gap: 9px; }
.friend-card {
  display: flex; align-items: center; gap: 14px;
  padding: 14px 16px; border: 1px solid var(--line); border-radius: 3px;
  background: rgba(255, 255, 255, 0.022);
}
.friend-card.locked { opacity: 0.52; }
.friend-glyph.big { flex: 0 0 auto; width: 42px; text-align: center; font-size: 30px; line-height: 1; color: var(--friend-color, var(--lumen)); text-shadow: 0 0 18px var(--friend-color, var(--lumen)); }
.friend-card div { min-width: 0; }
.friend-card strong { display: block; font-family: var(--serif); font-size: 18px; font-weight: 500; }
.friend-card div span { display: block; margin-top: 2px; font-size: 10.5px; line-height: 1.4; color: var(--faint); }
.friend-card b { margin-left: auto; flex: 0 0 auto; font-size: 8px; letter-spacing: 0.14em; color: var(--lumen); text-transform: uppercase; }
.friend-card.locked b { color: var(--faint); }

/* Travel */
.travel-list { display: grid; gap: 10px; }
.travel-option {
  display: flex; align-items: center; gap: 16px; width: 100%; padding: 16px 18px;
  border: 1px solid var(--line); border-radius: 3px; background: rgba(255, 255, 255, 0.02);
  color: var(--ink); text-align: left; transition: border-color 0.2s, background 0.2s;
}
.travel-option:not(:disabled):hover { border-color: rgba(127, 230, 255, 0.45); background: rgba(127, 230, 255, 0.06); }
.travel-option:disabled { opacity: 0.4; cursor: not-allowed; }
.travel-option .t-glyph { font-family: var(--serif); font-size: 26px; color: var(--accent); width: 38px; text-align: center; }
.travel-option strong { display: block; font-family: var(--serif); font-size: 19px; font-weight: 500; }
.travel-option span { display: block; margin-top: 2px; font-size: 9px; letter-spacing: 0.15em; text-transform: uppercase; color: var(--faint); }
.travel-option .t-state { margin-left: auto; font-size: 9px; letter-spacing: 0.12em; text-transform: uppercase; color: var(--faint); }

#transition { position: absolute; inset: 0; z-index: 60; display: flex; flex-direction: column; align-items: center; justify-content: center; background: #04121f; opacity: 0; transition: opacity 0.5s ease; }
#transition.visible { opacity: 1; }
.transition-mark { font-size: 48px; color: var(--lumen); animation: spinRune 10s linear infinite; }
#transition h2 { margin: 18px 0 4px; font-family: var(--serif); font-weight: 400; font-size: clamp(34px, 6vw, 62px); letter-spacing: 0.08em; }
#transition p { margin: 0; font-size: 10px; letter-spacing: 0.34em; text-transform: uppercase; color: var(--faint); }

